def get_display_name(test_data: dict, fallback_name: str) -> str:
    # Check "name" key first
    if isinstance(test_data.get("name"), str) and test_data["name"].strip():
        return test_data["name"]

    # Check "test" key second
    if isinstance(test_data.get("test"), str) and test_data["test"].strip():
        return test_data["test"].title()

    # Fallback to original folder name
    return fallback_name
